(r, big) => {
    const els = ["H", "He", "C", "N", "O", "Na", "Cl", "Fe", "Zz", "Ab"];
    const cnt = () => r.bool(0.5) ? "" : String(r.int(2, big ? 9 : 12));
    const form = (d, len) => {
      let s = "";
      for (let i = 0; i < len; i++) {
        if (d > 0 && r.bool(0.3)) s += "(" + form(d - 1, r.int(1, 3)) + ")" + cnt();
        else s += r.pick(els) + cnt();
      }
      return s;
    };
    if (!big) return [form(2, r.int(1, 4))];
    let s = "";
    while (s.length < 700) s += form(3, 2);
    return [s];
  }

