function tallyAtoms(formula: string): string {
  let i = 0;
  const readNum = (): number => {
    let j = i;
    while (i < formula.length && formula[i] >= "0" && formula[i] <= "9") i++;
    return i > j ? Number(formula.slice(j, i)) : 1;
  };
  const parse = (): Map<string, number> => {
    const m = new Map<string, number>();
    while (i < formula.length && formula[i] !== ")") {
      if (formula[i] === "(") {
        i++;
        const inner = parse();
        i++; // skip ')'
        const k = readNum();
        for (const [el, c] of inner) m.set(el, (m.get(el) ?? 0) + c * k);
      } else {
        const j = i++;
        while (i < formula.length && formula[i] >= "a" && formula[i] <= "z") i++;
        const el = formula.slice(j, i);
        m.set(el, (m.get(el) ?? 0) + readNum());
      }
    }
    return m;
  };
  const total = parse();
  return [...total.keys()].sort().map(el => el + (total.get(el)! > 1 ? total.get(el) : "")).join("");
}

