            return int(formula[j:i]) if i > j else 1

        def parse():
            nonlocal i
            m = Counter()
            while i < n and formula[i] != ")":
                if formula[i] == "(":
                    i += 1
                    inner = parse()
                    i += 1  # skip ')'
                    k = read_num()
                    for el, c in inner.items():
                        m[el] += c * k
                else:
                    j = i
                    i += 1
                    while i < n and formula[i].islower():
                        i += 1
                    el = formula[j:i]
                    m[el] += read_num()
            return m

        total = parse()
        return "".join(el + (str(total[el]) if total[el] > 1 else "") for el in sorted(total))

