function tallyAtoms(formula: string): string {
  const n = formula.length;
  const stack: Map<string, number>[] = [new Map()];
  let i = 0;
  const readNum = (): number => {
    const j = i;
    while (i < n && formula[i] >= "0" && formula[i] <= "9") i++;
    return i > j ? Number(formula.slice(j, i)) : 1;
  };
  while (i < n) {
    const ch = formula[i];
    if (ch === "(") {
      stack.push(new Map());
      i++;
    } else if (ch === ")") {
      i++;
      const k = readNum();
      const group = stack.pop()!, top = stack[stack.length - 1];
      for (const [el, c] of group) top.set(el, (top.get(el) ?? 0) + c * k);
    } else {
      const j = i++;
      while (i < n && formula[i] >= "a" && formula[i] <= "z") i++;
      const el = formula.slice(j, i);
      const top = stack[stack.length - 1];
      top.set(el, (top.get(el) ?? 0) + readNum());
    }
  }
  const total = stack[0];
  let out = "";
  for (const el of [...total.keys()].sort()) out += el + (total.get(el)! > 1 ? total.get(el) : "");
  return out;
}

